function useStage(steps: number[]) {
  const [stage, setStage] = createState(0);
  watchLifecycle(() => {
    if (stage.value >= steps.length) return;
    const t = setTimeout(() => setStage(s => s + 1), steps[stage.value]);
    return () => clearTimeout(t);
  }, () => [stage.value, steps]);
  return computed(() => {
    return stage.value;
  });
}
