  lineMode?: boolean;
  lineData?: LivelinePoint[];
  lineValue?: number;

  // Multi-series mode
  multiSeries?: Array<{
    id: string;
    data: LivelinePoint[];
    value: number;
    palette: LivelinePalette;
    label?: string;
